import pyomo.environ as pyo

DATA = {
    "products": ["syrup", "candy"],
    "profit": {"syrup": 20, "candy": 15},
    "hours_per_kg": {"syrup": 2, "candy": 2},
    "hours_available": 20,          # boiling station hours per day
    "max_prod": {"syrup": 10, "candy": 12},
    "min_prod": {"syrup": 3,  "candy": 5},
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])

    # kg produced per day of each product, bounded by its stated max
    model.x = pyo.Var(
        model.P,
        domain=pyo.NonNegativeReals,
        bounds=lambda m, p: (0, d["max_prod"][p]),
    )

    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    def max_prod_rule(m, p):
        return m.x[p] <= d["max_prod"][p]

    def min_prod_rule(m, p):
        return m.x[p] >= d["min_prod"][p]

    def boiling_rule(m):
        return sum(d["hours_per_kg"][p] * m.x[p] for p in m.P) <= d["hours_available"]

    def profit_rule(m):
        return pyo.quicksum(d["profit"][p] * m.x[p] for p in m.P)

    model.max_prod = pyo.Constraint(model.P, rule=max_prod_rule)
    model.min_prod = pyo.Constraint(model.P, rule=min_prod_rule)
    model.boiling = pyo.Constraint(rule=boiling_rule)
    model.obj = pyo.Objective(rule=profit_rule, sense=pyo.maximize)

    return model


